using namespace std;

class Solution {
public:
    int minInversions(vector<int>& nums, int k) {
        int n = nums.size();
        if (k <= 1) return 0;
        int ans = INT_MAX;
        for (int i = 0; i <= n - k; i++) {
            int inv = 0;
            for (int a = i; a < i + k; a++) {
                for (int b = a + 1; b < i + k; b++) {
                    if (nums[a] > nums[b]) inv++;
                }
            }
            ans = min(ans, inv);
        }
        return ans;
    }
};

class Solution {
    public int minInversions(int[] nums, int k) {
