        if (k <= 1) return 0;
        int ans = Integer.MAX_VALUE;
        for (int i = 0; i <= n - k; i++) {
            int inv = 0;
            for (int a = i; a < i + k; a++) {
                for (int b = a + 1; b < i + k; b++) {
                    if (nums[a] > nums[b]) inv++;
                }
            }
            ans = Math.min(ans, inv);
        }
